#!/bin/sh
# Prints the Homebrew formula for one release, for the tap at
# Blaise1030/homebrew-tap (`brew install blaise1030/tap/orso`).
# usage: homebrew-formula.sh <version> <dir holding the release's *.tar.gz.sha256 files>
set -eu
version=$1
dir=$2

sha() { cut -d' ' -f1 "$dir/orso-v$version-$1.tar.gz.sha256"; }
url() { echo "https://github.com/Blaise1030/CMS/releases/download/v$version/orso-v$version-$1.tar.gz"; }

cat <<FORMULA
# Generated by .github/scripts/homebrew-formula.sh in Blaise1030/CMS on each release; don't edit.
class Orso < Formula
  desc "Local Lovable-style site builder daemon"
  homepage "https://github.com/Blaise1030/CMS"
  version "$version"

  on_macos do
    on_arm do
      url "$(url aarch64-apple-darwin)"
      sha256 "$(sha aarch64-apple-darwin)"
    end
    on_intel do
      url "$(url x86_64-apple-darwin)"
      sha256 "$(sha x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_arm do
      url "$(url aarch64-unknown-linux-gnu)"
      sha256 "$(sha aarch64-unknown-linux-gnu)"
    end
    on_intel do
      url "$(url x86_64-unknown-linux-gnu)"
      sha256 "$(sha x86_64-unknown-linux-gnu)"
    end
  end

  def install
    bin.install "orso"
  end

  test do
    assert_match "Usage:", shell_output("#{bin}/orso --help")
  end
end
FORMULA
